"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1253-01-01:1":{"b": ["Mendog przyjął chrześcijaństwo i został koronowany na króla Litwy", "424666af"], "d": ["Mendog przeszedł w 1253 roku na katolicyzm i został koronowany na króla, ogłaszając Litwę królestwem; jego następcy powrócili do pogaństwa.", "fc42f619"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1255-01-01:0":{"b": ["Dla króla Czech Ottokara II zbudowano zamek Zakonu Krzyżackiego: Królewiec", "4b6bb21c"], "d": ["Miasto, które wyrosło wokół zamku zbudowanego dla Zakonu Krzyżackiego podczas krucjaty króla Ottokara II w Prusach (1255), otrzymało na jego cześć nazwę Königsberg. Miasto zostało zniszczone w 1263 roku w powstaniu Prusów i odbudowane w 1286 roku.", "7bc46742"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1257-01-01:0":{"b": ["Guglielmo Boccanegra ustanowił Kapitanat Ludu", "b7753984"], "d": ["Po śmierci Fryderyka II w 1250 roku mieszczaństwo wobec dawnych i nowych rodów szlacheckich (Fieschi, Grimaldi, Doria, Spinola) ustanowiło w 1257 roku pod wodzą Guglielma Boccanegry urząd „Kapitana Ludu” (capitano del Popolo); próba dyktatury Boccanegry została stłumiona w 1262 roku.", "2eae2a56"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1258-08-11:0":{"b": ["Manfred koronowany w Palermo na króla Sycylii", "95db5116"], "d": ["Manfred, który rozpowszechnił pogłoskę o śmierci swego bratanka Konradyna, odebrał królestwo legatowi papieskiemu przy poparciu muzułmanów z Lucery i został koronowany w Palermo na króla w 1258 roku.", "1047b259"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1259-01-01:0":{"b": ["Despota Epiru Michał II przekazał Korfu Manfredowi", "19f2de3c"], "d": ["W 1259 roku despota Epiru Michał II Angelos Komnen przekazał Korfu królowi Sycylii Manfredowi; wyspa przeszła w 1267 roku wraz z Królestwem Sycylii na Karola d'Anjou i stała się morską bazą andegaweńskich wpływów na Bałkanach.", "1fe50b1f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1260-01-01:0":{"b": ["Bitwa pod Montaperti: gibelińscy sprzymierzeńcy Manfreda pokonali toskańskich gwelfów; Florencja ponownie gibelińska", "7ee3d67e"], "d": ["Zwycięstwo pod Montaperti w 1260 roku było szczytem pomyślności Manfreda; Florencja przeszła ponownie pod rządy gibelińskie. Klęska Manfreda pod Benewentem (1266) i Tagliacozzo (1268) przyniosły powrót gwelfów.", "a3001f03"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1261-01-01:0":{"b": ["Układ z Nymphaion: Genua uzyskała od Bizancjum przywileje handlowe na Morzu Czarnym i wschodnim Morzu Śródziemnym", "194b1f15"], "d": ["Dzięki układowi z Nymphaion, podpisanemu w 1261 roku z cesarzem bizantyńskim Michałem VIII, Genua uzyskała szerokie przywileje na Morzu Czarnym i wschodnim Morzu Śródziemnym; ten układ jest podstawą kolonii Pera-Galata i kolonizacji Krymu (Kaffa).", "6deda3b0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-01-01:0":{"b": ["Bonifacy umiera bezdzietnie; jego stryj Piotr II zostaje hrabią Sabaudii", "38fe8bbd"], "d": ["Gdy małoletni syn Amadeusza IV, Bonifacy, zmarł w 1263 roku bezdzietnie, wbrew woli ojca hrabią został nie syn Tomasza II, Tomasz III, lecz jego brat Piotr II („Mały Karol Wielki”).", "c18af671"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-01-01:1":{"b": ["Pod Settepozzi Genua przegrała z Wenecją; podpisano rozejm w Cremonie", "060e901b"], "d": ["Wojna genueńsko-wenecka, trwająca po układzie z Nymphaion, zakończyła się w 1263 roku klęską Genui pod Settepozzi i rozejmem w Cremonie.", "83eacbcb"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-01-01:2":{"b": ["Prusowie zbuntowali się i zniszczyli pierwsze jądro Królewca", "9b09b809"], "d": ["Prusowie, którzy w 1263 roku zbuntowali się przeciw chrześcijańskim osadnikom, zniszczyli pierwsze jądro Królewca; miasto odbudowano w dzisiejszym miejscu (prawa miejskie w 1286).", "63cc141a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-12-16:0":{"b": ["Haakon IV umiera na Orkadach po bitwie pod Largs", "7df398fd"], "d": ["Haakon IV, który w 1263 roku wyruszył na Hebrydy, aby umocnić norweskie roszczenia w Szkocji, zmarł na Orkadach po bitwie pod Largs; skończyły się jego rządy trwające od 1217 roku. Jego syn Magnus Lagabøte zakończył wojnę ze Szkocją.", "a7f678c4"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1266-02-26:0":{"b": ["Bitwa pod Benewentem: Karol d'Anjou pokonał i zabił Manfreda; królestwo przeszło na Andegawenów", "40101cec"], "d": ["26 lutego 1266 roku pod Benewentem hrabia Andegawenii Karol rozgromił armię Manfreda; Manfred poległ na polu bitwy. Królestwo Sycylii przeszło z dynastii Hohenstaufów na dynastię andegaweńską.", "35ac3334"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1268-01-01:0":{"b": ["Umiera Piotr II; jego brat Filip I zostaje hrabią Sabaudii", "26cea9a1"], "d": ["Gdy Piotr II zmarł w 1268 roku bez męskiego potomka, prawa Tomasza III znów zostały pominięte; hrabią Sabaudii został jego brat Filip I. Po śmierci Filipa (1285) hrabstwo przeszło na Amadeusza V.", "74420d2e"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1272-01-01:0":{"b": ["Lew Daniłowicz przeniósł stolicę do Lwowa", "1c030990"], "d": ["Lew Daniłowicz przeniósł stolicę do Lwowa.", "d6c8561a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1278-08-26:0":{"b": ["Bitwa na Morawskim Polu (Dürnkrut): Ottokar II ginie, pokonany przez Rudolfa Habsburga", "a3d38659"], "d": ["Po wyborze Rudolfa Habsburga na króla Rzymian (1273) zażądano od Ottokara zwrotu lenn cesarskich, a Ottokar zrzekł się wszystkich ziem poza Czechami i Morawami. Atakując w 1278 roku księstwa austriackie, Ottokar został pokonany i zginął w bitwie pod Dürnkrut na Morawskim Polu.", "683f6e78"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1280-05-09:0":{"b": ["Magnus Lagabøte umiera w Bergen", "1f4309b2"], "d": ["Magnus Lagabøte („Naprawiacz Prawa”), syn Haakona IV, zmarł 9 maja 1280 roku w Bergen; został pochowany w franciszkańskim kościele Olavskirke.", "7c2cd8c3"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1328-08-16:0":{"b": ["W Mantui Luigi Gonzaga powstaje przeciw signorii Bonacolsich i przejmuje władzę; zaczyna się epoka Gonzagów", "1bd79932"], "d": ["16 sierpnia 1328 roku Luigi Gonzaga powstał przeciw signorii Bonacolsich rządzącej Mantuą i przejął władzę nad miastem. To samo miasto-państwo trwało z nową dynastią; Gonzagowie rządzili Mantuą do 1708 roku.", "1c4bea74"]},
"OLAYLAR_ORTACAG_ORTADOGU:0634-03-07:0":{"b": ["Chalid b. al-Walid zdobył Tadmur (Palmyrę) drogą pokojową (13/634)", "70032222"], "d": ["Tadmur (Palmyra) została zdobyta przez Chalida b. al-Walida drogą pokojową; przeszła spod władzy Cesarstwa Bizantyńskiego (Wschodniorzymskiego) pod zarząd kalifów rasziduńskich (kalifatu medyńskiego). TDV wspomina też, że po złamaniu układu przez mieszkańców miasto zostało ponownie zdobyte siłą przez Dihję b. Chalifę al-Kalbiego (bez daty).", "e143bd53"]},
