"OLAYLAR_ORTACAG_ORTADOGU:1250-04-05:0":{"b": ["Po zabiciu Turan Szaha przez Mameluków an-Nasir Jusuf, na zaproszenie emirów Syrii, zajął Damaszek bez walki (648/1250); linia aleppańska rządziła także Syrią.", "3f4f40d7"], "d": ["Po zabiciu Turan Szaha przez Mameluków an-Nasir Jusuf, na zaproszenie emirów Syrii, zajął Damaszek bez walki (648/1250); linia aleppańska rządziła także Syrią.", "3f4f40d7"]},
"OLAYLAR_ORTACAG_ORTADOGU:1250-04-07:0":{"b": ["Al-Mansura: muzułmanie zadali ostateczną klęskę armii krzyżowej Ludwika IX", "8d1db119"], "d": ["W walkach trwających od początku marca do 7 kwietnia 1250 krzyżowcy ponieśli ostateczną klęskę; król wraz z otoczeniem miał zostać uwolniony w zamian za zwrot Damietty i wysoki okup.", "4c176422"]},
"OLAYLAR_ORTACAG_ORTADOGU:1250-05-07:0":{"b": ["Damietta została zwrócona muzułmanom", "f7070829"], "d": ["W zamian za uwolnienie króla Damietta została przekazana muzułmanom 7 maja 1250.", "16c1ec7a"]},
"OLAYLAR_ORTACAG_ORTADOGU:1251-02-03:0":{"b": ["An-Nasir Jusuf pokonał armię mameluków w bitwie pod Abbasa i w Kairze odczytano chutbę w jego imieniu; w 1253 zawarto pokój za pośrednictwem posła kalifa.", "1e4046b9"], "d": ["An-Nasir Jusuf pokonał armię mameluków w bitwie pod Abbasa i w Kairze odczytano chutbę w jego imieniu; w 1253 zawarto pokój za pośrednictwem posła kalifa.", "1e4046b9"]},
